package jp.tapmarker;
import java.util.*;import java.util.regex.*;
public final class PromptLogic {
 public static class Plan {public int action=4,waitMs=800;public float changeThreshold=.004f;public boolean record=false,strict=false,stopOnChange=false,completionRequested=false;public String interpretation(){if(action==6)return "条件：監視領域が変化し、閾値を超えたら\n操作：監視領域の中央を1回タップ\n初回観測：基準登録のみ\nタップ後："+waitMs+"ms待機して基準を取り直す\n変化閾値："+changeThreshold+(completionRequested?"\n完了学習の状態で停止":"")+"\n経路学習・マーカー不要。保存後に自律開始";return "操作："+(action==5?"登録した曲線をなぞる":"登録したマーカーを連打")+"\n監視：指定領域のみ\n遷移："+(record?"観測した遷移を記録":strict?"記録済みの遷移だけ実行":"学習済み画面から選択")+"\n操作後待機："+waitMs+"ms / 変化閾値："+changeThreshold+(stopOnChange?"\n領域変化で停止":"")+"\n完了学習の画面で停止\n保存後に「経路学習」で現在の画面へ紐づけ";}}
 public static Plan parse(String text){Plan p=new Plan();boolean found=false,mode=false;for(String raw:text.split("[。；;"+String.valueOf((char)10)+"]+")){String clause=raw.replaceAll("\\s+","");if(clause.isEmpty())continue;found=true;if(clause.equals("監視領域が変わるまでマーカーを連打")||clause.equals("マーカーを連打")){if(mode&&p.action!=4)throw new IllegalArgumentException("操作が矛盾しています");p.action=4;mode=true;}else if(clause.equals("監視領域が変わったら監視領域中央をタップ")||clause.equals("監視領域が変わったら監視領域の中央をタップ")){if(mode&&p.action!=6)throw new IllegalArgumentException("操作が矛盾しています");p.action=6;mode=true;}else if(clause.equals("描いた曲線をなぞる")||clause.equals("曲線をなぞる")||clause.equals("監視領域が変わるまで描いた曲線をなぞる")){if(mode&&p.action!=5)throw new IllegalArgumentException("操作が矛盾しています");p.action=5;mode=true;}else if(clause.equals("変化したら学習した次の操作へ")||clause.equals("記録済み遷移に従う")){if(p.record)throw new IllegalArgumentException("遷移記録と遷移実行は同時指定できません");p.strict=true;}else if(clause.equals("遷移を記録")){if(p.strict)throw new IllegalArgumentException("遷移記録と遷移実行は同時指定できません");p.record=true;}else if(clause.equals("監視領域が変わったら停止")||clause.equals("変化したら停止")){p.stopOnChange=true;}else if(clause.equals("完了で停止")){p.completionRequested=true;}else if(clause.equals("監視領域の変化を待つ")){}else if(clause.matches("待機[0-9]+(ミリ秒|ms)")){Matcher m=Pattern.compile("[0-9]+").matcher(clause);m.find();p.waitMs=Integer.parseInt(m.group());if(p.waitMs<250||p.waitMs>10000)throw new IllegalArgumentException("待機は250〜10000msです");}else if(clause.matches("変化しきい値[0-9]+(\\.[0-9]+)?")){p.changeThreshold=Float.parseFloat(clause.substring("変化しきい値".length()));if(p.changeThreshold<.00001f||p.changeThreshold>.1f)throw new IllegalArgumentException("変化しきい値は0.00001〜0.1です");}else throw new IllegalArgumentException("未対応："+raw.trim());}if(p.action==6&&(p.record||p.strict||p.stopOnChange))throw new IllegalArgumentException("中央タップと遷移記録・遷移制約・変化時停止は同時指定できません");if(!found)throw new IllegalArgumentException("指示を入力してください");return p;}
}
